/// The messages of Bento's `message.proto`, generated by `build.rs`.
pub mod messagepb {
    include!(concat!(env!("OUT_DIR"), "/messagepb.rs"));
}

use std::sync::OnceLock;

use messagepb::{part::Content, Batch, Part};
use prost::Message;
use serde::Deserialize;

/// The processor's config, which Bento passes to [`_init_plugin`] as JSON.
#[derive(Deserialize)]
struct Config {
    #[serde(default)]
    prefix: String,
}

/// The prefix added before each message, which is set once per instance.
static PREFIX: OnceLock<String> = OnceLock::new();

/// Reads the processor's config.
fn init(config: &[u8]) -> Result<(), String> {
    let config: Config = serde_json::from_slice(config).map_err(|e| e.to_string())?;
    PREFIX.set(config.prefix).map_err(|_| "already initialised".to_string())
}

/// Uppercases a message, after the prefix, and records that it processed it.
fn process(mut part: Part) -> Batch {
    let prefix = PREFIX.get().map(String::as_str).unwrap_or_default();
    if let Some(Content::Raw(raw)) = &mut part.content {
        *raw = [prefix, &String::from_utf8_lossy(raw).to_uppercase()].concat().into_bytes();
    }
    part.metadata.insert("processed_by".into(), "uppercase_wasm".into());
    Batch { parts: vec![part] }
}

//------------------------------------------------------------------------------

/// WebAssembly export that is called once per instance with the processor's
/// config as JSON, and returns an error, which is empty on success.
#[cfg_attr(target_arch = "wasm32", export_name = "init_plugin")]
pub unsafe extern "C" fn _init_plugin(ptr_size: u64) -> u64 {
    let config_ptr = (ptr_size >> 32) as u32;
    let config_size = ptr_size as u32;
    let config = ptr_to_bytes(config_ptr, config_size);

    let error = match init(config) {
        Ok(()) => Vec::new(),
        Err(err) => err.into_bytes(),
    };
    let error = error.into_boxed_slice();

    let error_ptr_size = bytes_to_ptr_size(&error);
    std::mem::forget(error);
    error_ptr_size
}

/// The result area of a call, which Bento reads after it returns: the buffer
/// of its output, then the buffer of its error, which is empty on success.
#[repr(C)]
pub struct CallResult {
    output: u64,
    error: u64,
}

/// The result area of the last call. It's static, so it remains valid after
/// the call returns, until the next call.
static mut RESULT: CallResult = CallResult { output: 0, error: 0 };

/// WebAssembly export that is called for each message being processed, and
/// returns the address of its result.
#[cfg_attr(target_arch = "wasm32", export_name = "process")]
pub unsafe extern "C" fn _process(ptr_size: u64) -> *const CallResult {
    let part_ptr = (ptr_size >> 32) as u32;
    let part_size = ptr_size as u32;
    let part = ptr_to_bytes(part_ptr, part_size);

    let (output, error) = match Part::decode(part) {
        Ok(part) => (process(part).encode_to_vec(), Vec::new()),
        Err(err) => (Vec::new(), err.to_string().into_bytes()),
    };
    let output = output.into_boxed_slice();
    let error = error.into_boxed_slice();

    let result = std::ptr::addr_of_mut!(RESULT);
    result.write(CallResult {
        output: bytes_to_ptr_size(&output),
        error: bytes_to_ptr_size(&error),
    });
    std::mem::forget(output);
    std::mem::forget(error);
    result
}

//------------------------------------------------------------------------------

/// Returns bytes from WebAssembly compatible numeric types representing their
/// pointer and length.
///
/// Note: This doesn't take ownership of the bytes, which Bento frees once the
/// call returns.
unsafe fn ptr_to_bytes<'a>(ptr: u32, len: u32) -> &'a [u8] {
    if len == 0 {
        return &[];
    }
    std::slice::from_raw_parts(ptr as *const u8, len as usize)
}

/// Returns the pointer and length of the given bytes in a way compatible with
/// WebAssembly numeric types: the pointer in the upper 32 bits, and the length
/// in the lower 32 bits, or zero when there are none.
///
/// Note: This doesn't change the ownership of the bytes. To return them to
/// Bento, which frees them with [`_release`], use [`std::mem::forget`] on the
/// input after calling this.
fn bytes_to_ptr_size(bytes: &[u8]) -> u64 {
    if bytes.is_empty() {
        return 0;
    }
    (bytes.as_ptr() as u64) << 32 | bytes.len() as u64
}

/// WebAssembly export that allocates a buffer for Bento to write the input of
/// a call into.
///
/// This is an ownership transfer, which means Bento calls [`_release`] once
/// the call returns.
#[cfg_attr(target_arch = "wasm32", export_name = "alloc")]
pub extern "C" fn _alloc(size: u32) -> *mut u8 {
    allocate(size as usize)
}

/// Allocates size bytes and leaks the pointer where they start.
fn allocate(size: usize) -> *mut u8 {
    Box::into_raw(vec![0u8; size].into_boxed_slice()) as *mut u8
}

/// WebAssembly export that frees a buffer allocated by [`_alloc`], or returned
/// to Bento by a call.
#[cfg_attr(target_arch = "wasm32", export_name = "release")]
pub unsafe extern "C" fn _release(ptr: *mut u8, size: u32) {
    deallocate(ptr, size as usize);
}

/// Retakes the pointer which allows its memory to be freed.
///
/// Note: The size must be the buffer's, as it's freed as a boxed slice.
unsafe fn deallocate(ptr: *mut u8, size: usize) {
    drop(Box::from_raw(std::ptr::slice_from_raw_parts_mut(ptr, size)));
}
